import sqlite3

def pending(path):
    with sqlite3.connect(path) as connection:
        connection.execute("CREATE TABLE IF NOT EXISTS parcels (id INTEGER PRIMARY KEY, label TEXT, status TEXT)")
        return connection.execute("SELECT label FROM parcels WHERE status = ?", ("pending",)).fetchall()

